#pragma once
#include "engine.hpp"
#include <memory>
#include <tuple>

namespace planner {
using I64 = long long;
constexpr I64 INF = (I64(1)<<60);
struct Cost {
    I64 work=INF;
    int pages=1000000000;
};
inline bool better(const Cost& a, const Cost& b) {
    return a.work<b.work || (a.work==b.work && a.pages<b.pages);
}
inline Cost add(const Cost& a, const Cost& b) { return {a.work+b.work,a.pages+b.pages}; }
struct WorkBurst { I64 repeat; std::vector<int> ranks; };
struct RootChoice { short b=-1; unsigned char mode=0,cached=0; };
struct SplitChoice { short split=-1,left_budget=-1; };

// D(i,j,p): best tree on [i,j) using exactly p resident pages.
// F(b,i,j,p): best ordered forest of exactly b nonempty trees on [i,j).
// F(1) is D; for b>=2, split off its last tree and convolve budgets.
// Every child interval is strictly shorter than its parent, so increasing
// interval length makes this an acyclic, exhaustive dynamic program. Each
// interval's Q,T is independent of topology, and a root's cost depends only
// on its encoding, child count and residency, making optimal substructure
// exact even for bursts. Both work and image pages are carried lexicographically.
class Solver {
    const std::vector<Key>& starts;
    int n,N,B,S,hit,miss;
    std::array<int,3> decode;
    std::vector<Cost> d,f;
    std::vector<RootChoice> roots;
    std::vector<SplitChoice> splits;
    std::vector<I64> qprefix,touch;
    size_t index(int i,int j,int p) const { return (size_t(i)*N+j)*S+p; }
    size_t fi(int b,int i,int j,int p) const { return (size_t(b)*N*N+size_t(i)*N+j)*S+p; }
    Cost& D(int i,int j,int p) { return d[index(i,j,p)]; }
    Cost& F(int b,int i,int j,int p) { return f[fi(b,i,j,p)]; }
    void root_candidate(int i,int j,int b,int mode,int cached,I64 q,I64 t) {
        int pages=node_pages(j-i,b,mode),used=cached ? pages : 0;
        if (used>B) return;
        int k=b ? b-1 : j-i;
        I64 work=I64(pages)*(cached ? hit : miss)*t
                    + I64((k+LANES[mode]-1)/LANES[mode]+decode[mode])*q;
        Cost own{work,pages};
        int last=b ? B-used : 0;
        for (int p=0;p<=last;++p) {
            Cost sub=b ? F(b,i,j,p) : Cost{0,0};
            if (sub.work==INF) continue;
            Cost candidate=add(own,sub);
            if (better(candidate,D(i,j,p+used))) {
                D(i,j,p+used)=candidate;
                roots[index(i,j,p+used)]={short(b),static_cast<unsigned char>(mode),static_cast<unsigned char>(cached)};
            }
        }
    }
    void forest_ranges(int b,int i,int j,int p,std::vector<std::tuple<int,int,int>>& out) {
        if (b==1) {out.emplace_back(i,j,p);return;}
        SplitChoice c=splits[fi(b,i,j,p)];
        forest_ranges(b-1,i,c.split,c.left_budget,out);
        out.emplace_back(c.split,j,p-c.left_budget);
    }
    int make_tree(int i,int j,int p,std::vector<Layout>& nodes) {
        RootChoice c=roots[index(i,j,p)];
        if (c.b<0) throw std::runtime_error("unreachable planning state");
        Layout node;
        node.lo=i; node.span=j-i; node.mode=c.mode; node.cached=c.cached;
        int id=nodes.size(); nodes.push_back(node);
        if (c.b) {
            int remain=p-(c.cached ? node_pages(j-i,c.b,c.mode) : 0);
            std::vector<std::tuple<int,int,int>> ranges;
            forest_ranges(c.b,i,j,remain,ranges);
            std::vector<int> children;
            for (auto range:ranges) {
                int l,r,budget; std::tie(l,r,budget)=range;
                children.push_back(make_tree(l,r,budget,nodes));
            }
            nodes[id].children=std::move(children);
        }
        return id;
    }
public:
    Solver(const std::vector<Key>& keys,const std::vector<WorkBurst>& bursts,int budget,
           int h,int m,std::array<int,3> dec)
        : starts(keys),n(keys.size()),N(n+1),B(budget),S(B+1),hit(h),miss(m),decode(dec),
          d(size_t(N)*N*S),f(size_t(10)*N*N*S),roots(size_t(N)*N*S),
          splits(size_t(10)*N*N*S),qprefix(N,0),touch(size_t(N)*N,0) {
        std::vector<I64> freq(n,0);
        for (const auto& burst:bursts) {
            std::vector<int> distinct=burst.ranks;
            for (int r:distinct) freq[r]+=burst.repeat;
            std::sort(distinct.begin(),distinct.end());
            distinct.erase(std::unique(distinct.begin(),distinct.end()),distinct.end());
            size_t k=0;
            for (int i=0;i<n;++i) {
                while (k<distinct.size() && distinct[k]<i) ++k;
                if (k==distinct.size()) break;
                for (int j=distinct[k]+1;j<=n;++j) touch[i*N+j]+=burst.repeat;
            }
        }
        for (int i=0;i<n;++i) qprefix[i+1]=qprefix[i]+freq[i];
        for (int len=1;len<=n;++len) for (int i=0;i+len<=n;++i) {
            int j=i+len;
            for (int b=2;b<=std::min(9,len);++b) {
                Cost* target=&F(b,i,j,0);
                SplitChoice* choices=&splits[fi(b,i,j,0)];
                for (int split=i+b-1;split<j;++split) {
                    const Cost* left=b==2 ? &D(i,split,0) : &F(b-1,i,split,0);
                    const Cost* right=&D(split,j,0);
                    for (int a=0;a<=B;++a) if (left[a].work!=INF) {
                        for (int c=0;c<=B-a;++c) if (right[c].work!=INF) {
                            Cost candidate=add(left[a],right[c]);
                            if (better(candidate,target[a+c])) {
                                target[a+c]=candidate;
                                choices[a+c]={short(split),short(a)};
                            }
                        }
                    }
                }
            }
            I64 q=qprefix[j]-qprefix[i],t=touch[i*N+j];
            Key spread=starts[j-1]-starts[i];
            for (int mode=0;mode<3;++mode) {
                if (mode && spread >= (Key(1)<<(mode==1 ? 64 : 32))) continue;
                for (int cached=0;cached<=1;++cached) {
                    if (len<=8) root_candidate(i,j,0,mode,cached,q,t);
                    for (int b=2;b<=std::min(9,len);++b) root_candidate(i,j,b,mode,cached,q,t);
                }
            }
        }
    }
    Cost result(int budget) const { return d[index(0,n,budget)]; }
    std::vector<Layout> layout(int budget) {
        std::vector<Layout> preorder;
        make_tree(0,n,budget,preorder);
        std::vector<int> order{0},ids(preorder.size());
        for (size_t p=0;p<order.size();++p) {
            int id=order[p];
            for (int child:preorder[id].children) order.push_back(child);
        }
        for (size_t p=0;p<order.size();++p) ids[order[p]]=p;
        std::vector<Layout> bfs;
        for (int id:order) {
            Layout node=preorder[id];
            for (int& child:node.children) child=ids[child];
            bfs.push_back(std::move(node));
        }
        return bfs;
    }
};
struct Version { std::vector<Key> starts; std::vector<int> hops; };
struct Burst { int version; I64 repeat; std::vector<Key> addresses; };

// Private batched interface used by the Python JSON driver. The public native
// stages remain ATLAS/PACK/TRACE, and all final paths use their same byte kernel.
inline void optimize_stage() {
    int vcount,budget,hit,miss; std::array<int,3> decode;
    std::cin>>vcount>>budget>>hit>>miss>>decode[0]>>decode[1]>>decode[2];
    std::vector<Version> versions(vcount);
    for (auto& version:versions) {
        int r; std::cin>>r;
        for (int i=0;i<r;++i) {
            std::string s; int hop; std::cin>>s>>hop;
            version.starts.push_back(key(s)); version.hops.push_back(hop);
        }
    }
    int nb; std::cin>>nb;
    std::vector<Burst> bursts(nb);
    std::vector<std::vector<WorkBurst>> workloads(vcount);
    for (auto& burst:bursts) {
        int count; std::cin>>burst.version>>burst.repeat>>count;
        WorkBurst work; work.repeat=burst.repeat;
        auto& starts=versions[burst.version].starts;
        for (int k=0;k<count;++k) {
            std::string s; std::cin>>s;
            Key x=key(s); burst.addresses.push_back(x);
            work.ranks.push_back(std::upper_bound(starts.begin(),starts.end(),x)-starts.begin()-1);
        }
        workloads[burst.version].push_back(std::move(work));
    }
    std::vector<std::unique_ptr<Solver>> solvers;
    std::vector<Cost> global(budget+1); global[0]={0,0};
    std::vector<std::vector<int>> choices(vcount,std::vector<int>(budget+1,-1));
    for (int v=0;v<vcount;++v) {
        solvers.emplace_back(new Solver(versions[v].starts,workloads[v],budget,hit,miss,decode));
        std::vector<Cost> next(budget+1);
        for (int a=0;a<=budget;++a) if (global[a].work!=INF) {
            for (int c=0;c<=budget-a;++c) {
                Cost root=solvers.back()->result(c);
                if (root.work==INF) continue;
                Cost candidate=add(global[a],root);
                if (better(candidate,next[a+c])) { next[a+c]=candidate; choices[v][a+c]=c; }
            }
        }
        global=std::move(next);
    }
    int best=0;
    for (int p=1;p<=budget;++p) if (better(global[p],global[best])) best=p;
    Cost objective=global[best];
    for (const auto& version:versions) objective.pages+=1+(4*version.starts.size()+63)/64;
    std::cout<<objective.work<<' '<<objective.pages<<'\n';
    std::vector<int> allocation(vcount);
    for (int v=vcount-1,p=best;v>=0;--v) {allocation[v]=choices[v][p];p-=allocation[v];}
    std::vector<Bytes> images;
    for (int v=0;v<vcount;++v) {
        images.push_back(build_image(versions[v].starts,versions[v].hops,solvers[v]->layout(allocation[v])));
        std::cout<<tohex(images.back())<<'\n';
    }
    for (const auto& burst:bursts) for (Key x:burst.addresses) print_answer(lookup_image(images[burst.version],x));
}
} // namespace planner
